package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.util.*;
/** Local launcher profiles, deliberately separate from streaming accounts. No photos/account access. */
final class ProfileAvatars {
    static final String KEY="profile_avatar_v1";
    static final String[] NAMES={"Ocean","Sunset","Forest","Lilac","Rose","Slate"};
    static final int[] COLORS={0xff365c83,0xff8c4636,0xff326251,0xff655484,0xff85445d,0xff465467};
    static String label(Context c){for(LocalProfiles.Profile p:ProfileStore.read(c))if(p.id.equals(ProfileStore.id()))return p.name;return "Current layout";}
    static void settings(Activity a){String current=ProfileStore.preferences(a).getString(KEY,"Ocean");new AlertDialog.Builder(a).setTitle("Profile avatar color").setSingleChoiceItems(NAMES,Arrays.asList(NAMES).indexOf(current),(d,n)->{ProductFeatures.beforeChange(a,"Change profile avatar");Map<String,Object> values=new HashMap<>();values.put(KEY,NAMES[n]);values.put(Config.SETTINGS_REVISION_KEY,ProfileStore.preferences(a).getLong(Config.SETTINGS_REVISION_KEY,0)+1);if(SetupValues.commit(ProfileStore.preferences(a),values)){d.dismiss();a.finish();}else Toast.makeText(a,"Could not save avatar",Toast.LENGTH_LONG).show();}).setNegativeButton(android.R.string.cancel,null).show();}
    static void show(Activity a,boolean allowImport){Config.load(a);List<String> ids=new ArrayList<>(),names=new ArrayList<>();ids.add("");names.add("Current layout");for(LocalProfiles.Profile p:ProfileStore.read(a)){ids.add(p.id);names.add(p.name);}int dp=Math.max(1,Math.round(a.getResources().getDisplayMetrics().density));ScrollView scroll=new ScrollView(a);GridLayout grid=new GridLayout(a);grid.setColumnCount(Math.max(1,Math.min(4,(int)((a.getResources().getDisplayMetrics().widthPixels*.56-64*dp)/(148*dp)))));grid.setPadding(18*dp,12*dp,18*dp,12*dp);scroll.addView(grid);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Who’s watching?").setMessage("Choose a launcher profile. This does not switch accounts inside Netflix or other apps.").setView(scroll).setNegativeButton("Back",null).create();View[] selected={null};
        for(int i=0;i<ids.size();i++){final String id=ids.get(i),name=names.get(i);LinearLayout tile=new LinearLayout(a);tile.setOrientation(LinearLayout.VERTICAL);tile.setGravity(Gravity.CENTER);tile.setFocusable(true);tile.setClickable(true);tile.setPadding(10*dp,10*dp,10*dp,10*dp);tile.setBackgroundResource(R.drawable.settings_choice_bg);tile.setContentDescription(name+(id.equals(ProfileStore.id())?", selected":""));String color=ProfileSetup.global(a).getString(LocalProfiles.key(id,KEY),"Ocean");int at=Arrays.asList(NAMES).indexOf(color);TextView avatar=new TextView(a);avatar.setText(name.substring(0,name.offsetByCodePoints(0,Math.min(2,name.codePointCount(0,name.length())))).toUpperCase(Locale.getDefault()));avatar.setGravity(Gravity.CENTER);avatar.setTextColor(-1);avatar.setTextSize(25);GradientDrawable circle=new GradientDrawable();circle.setColor(COLORS[at<0?0:at]);circle.setShape(GradientDrawable.OVAL);avatar.setBackground(circle);tile.addView(avatar,new LinearLayout.LayoutParams(64*dp,64*dp));TextView caption=new TextView(a);caption.setText(name+(id.equals(ProfileStore.id())?" ✓":""));caption.setTextColor(-1);caption.setTextSize(15);caption.setMaxLines(2);caption.setEllipsize(android.text.TextUtils.TruncateAt.END);caption.setGravity(Gravity.CENTER);tile.addView(caption,new LinearLayout.LayoutParams(118*dp,-2));GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=142*dp;p.height=128*dp;p.setMargins(3*dp,3*dp,3*dp,3*dp);grid.addView(tile,p);if(id.equals(ProfileStore.id()))selected[0]=tile;tile.setOnClickListener(v->{if(id.equals(ProfileStore.id())){dialog.dismiss();return;}if(ProfileStore.select(a,id)){dialog.dismiss();if(a instanceof MainActivity)a.recreate();else a.finish();}else Toast.makeText(a,"Could not switch profile",Toast.LENGTH_LONG).show();});}
        if(allowImport)dialog.setButton(AlertDialog.BUTTON_NEUTRAL,a.getString(R.string.profile_import),(d,w)->{if(!ProfileStore.id().isEmpty()){Toast.makeText(a,R.string.profile_import_current,Toast.LENGTH_LONG).show();return;}if(!LauncherLock.require(a,()->show(a,true)))return;try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),ProfilePicker.IMPORT);}catch(Exception unavailable){Toast.makeText(a,R.string.not_available,Toast.LENGTH_LONG).show();}});
        dialog.setOnShowListener(d->{if(selected[0]!=null)selected[0].requestFocus();});dialog.show();
    }
}
